components.css:
.ds-button-primary{
  background: var(--green);
  color: white;
  border: 0;
  border-radius: 7px;
  font-weight: 600;
  padding: 12px 18px;
  min-height: 46px;
  transition: background 150ms;
font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.5;}.ds-button-primary:focus-visible{outline:3px solid #4d9170;outline-offset:3px;}.ds-button-primary:disabled{cursor:not-allowed;opacity:.55;}.ds-button-primary:hover:not(:disabled){
  background: #184c34;
}

.ds-button-text{
  background: transparent;
  border: 0;
  color: var(--green);
  text-decoration: underline;
  text-underline-offset: 4px;
  padding: 6px;
  font-size: 12px;
  min-height: 36px;
font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.5;}.ds-button-text:focus-visible{outline:3px solid #4d9170;outline-offset:3px;}.ds-button-text:disabled{cursor:not-allowed;opacity:.55;}.ds-button-text:hover:not(:disabled){
  color: #123c25;
}

.ds-button-danger{
  border: 0;
  background: var(--red);
  border-radius: 6px;
  color: white;
  font-size: 12px;
  padding: 9px 12px;
  min-height: 38px;
font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.5;}.ds-button-danger:focus-visible{outline:3px solid #4d9170;outline-offset:3px;}.ds-button-danger:disabled{cursor:not-allowed;opacity:.55;}

.ds-field{display:flex;flex-direction:column;gap:7px;font:600 13px/1.5 Arial,Helvetica,sans-serif;color:var(--ink);}.ds-input{
  width: 100%;
  min-height: 45px;
  padding: 10px 12px;
  color: var(--ink);
  border: 1px solid #c7d5cb;
  border-radius: 7px;
  background-color: var(--surface);
  transition: border-color 120ms;
font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.5;}.ds-input:hover:not(:disabled){border-color:#72927e;}.ds-input[aria-invalid="true"]{border-color:var(--red);}.ds-input:disabled{cursor:not-allowed;background:#edf1ee;}.ds-input::placeholder{color:#6d7c72;opacity:1;}.ds-input:focus-visible{outline:3px solid #4d9170;outline-offset:3px;}

.ds-panel{
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 26px;
  min-width: 0;
font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.5;color:var(--ink);}.ds-title{margin:0;font-size:20px;font-weight:600;letter-spacing:-.02em;}.ds-copy{margin:5px 0 0;font-size:13px;color:var(--muted);}@media(max-width:760px){.ds-panel{padding:21px;}}@media(max-width:380px){.ds-panel{padding:17px;}}

.ds-expense-count{
  border-radius: 6px;
  font-size: 12px;
  background: var(--green-light);
  color: var(--green);
  padding: 4px 9px;
  white-space: nowrap;
font-family:Arial,Helvetica,sans-serif;line-height:1.5;}

.ds-split-option{
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 8px;
  border-radius: 5px;
  color: var(--muted);
  cursor: pointer;

  color: var(--green);
  background: white;
  box-shadow: 0 2px 4px #1e3b2910;
display:flex;font:600 13px/1.5 Arial,Helvetica,sans-serif;}.ds-split-option input{accent-color:var(--green);width:16px;height:16px;flex-shrink:0;}.ds-split-option input:focus-visible{outline:3px solid #4d9170;outline-offset:3px;}
